/**
 * Where a planet's passes over the whole picture go on its camera, and the
 * depth they read. Imported only by the code-split passes
 * (contactShadowsChunk.ts, motionBlurChunk.ts), never by the main bundle.
 *
 * The temporal anti-aliasing's two passes go first, where the scene is drawn
 * at a share of the screen and rebuilt; the contact shadows and the motion
 * blur next, on the whole picture before the eye exposes it; every other
 * pass after them, in its own order. Without the anti-aliasing, the first of
 * them takes the scene, and with it the depth the scene was drawn with.
 */
import { Constants } from '@babylonjs/core/Engines/constants';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { PostProcess } from '@babylonjs/core/PostProcesses/postProcess';

/** The passes that go first, in this order. */
export const FIRST_PASSES = ['planetTemporal', 'planetTemporalCopy', 'planetContactShadows', 'planetMotionBlur'] as const;

const rank = (p: PostProcess | null): number => {
  const i = p ? (FIRST_PASSES as readonly string[]).indexOf(p.name) : -1;
  return i < 0 ? FIRST_PASSES.length : i;
};

/** Puts the camera's passes in order, keeping every other pass's own; nothing moves when they are in order already. */
export function keepInOrder(camera: Camera): void {
  const list = camera._postProcesses;
  let ordered = true;
  for (let i = 1; i < list.length && ordered; i++) ordered = rank(list[i]!) >= rank(list[i - 1]!);
  if (ordered) return;
  const sorted = list.map((p, i) => ({ p, i })).sort((a, b) => rank(a.p) - rank(b.p) || a.i - b.i).map((x) => x.p);
  list.splice(0, list.length, ...sorted);
}

/** The first pass on the camera, which the scene is drawn into. */
const firstOf = (camera: Camera): PostProcess | undefined => camera._postProcesses.find((p): p is PostProcess => !!p);

/** The depth the scene was drawn with this frame, on the first pass's own texture; null where there is none to read. */
export function sceneDepth(camera: Camera): NonNullable<PostProcess['inputTexture']['depthStencilTexture']> | null {
  return firstOf(camera)?.inputTexture?.depthStencilTexture ?? null;
}

/**
 * Where `pass` is first on the camera, the scene is drawn into its texture:
 * a depth texture is given to it there, as WebGL would otherwise draw the
 * depth into a buffer nothing can read.
 */
export function giveDepthIfFirst(camera: Camera, pass: PostProcess): void {
  if (firstOf(camera) !== pass) return;
  const target = pass.inputTexture;
  if (!target || target.depthStencilTexture || target.width <= 0) return;
  try {
    const engine = pass.getEngine();
    const stencil = engine.isStencilEnable;
    target.createDepthStencilTexture(0, false, stencil, 1, stencil ? Constants.TEXTUREFORMAT_DEPTH24_STENCIL8 : Constants.TEXTUREFORMAT_DEPTH32_FLOAT);
  } catch {
    /* an engine without depth textures: the pass reads none, and draws the picture as it is */
  }
}

/** The depth as the projection gives it from the 0 to 1 a depth texture holds: 0 to 1 on WebGPU, -1 to 1 on WebGL. */
export function depthNdcOf(halfZRange: boolean): [number, number] {
  return halfZRange ? [1, 0] : [2, -1];
}
